import fs from 'node:fs';import assert from 'node:assert/strict';import {DatabaseSync} from 'node:sqlite';
const before=await import('./stock-ledger-before-opt-20261028.mjs'),after=await import(new URL('../worker/src/stockLedger.ts',import.meta.url).href);
const db=new DatabaseSync(':memory:',{enableForeignKeyConstraints:false});db.exec(fs.readFileSync('artifacts/before-issue-target-correction-20261028.sql','utf8'));
const wh=db.prepare('SELECT warehouse_id FROM stock_movements LIMIT 1').get().warehouse_id,parts=db.prepare('SELECT DISTINCT part_id FROM stock_movements LIMIT 6').all().map(r=>r.part_id);
db.prepare("INSERT INTO app_users(id,auth_subject,email,display_name,role) VALUES ('local-perf-wh','local-perf-wh','perf@example.invalid','Local test','warehouse')").run();db.prepare('INSERT INTO document_warehouse_access(user_id,warehouse_id) VALUES (?,?)').run('local-perf-wh',wh);
let captured=[];class Statement{constructor(query,args=[]){this.query=query;this.args=args}bind(...args){return new Statement(this.query,args)}execute(){captured.push({query:this.query,args:this.args});return {results:db.prepare(this.query).all(...this.args)}}async first(){return this.execute().results[0]??null}}
const env={DB:{prepare:q=>new Statement(q),batch:async ss=>ss.map(s=>s.execute())}};
async function call(handler,params,user={id:'local-admin',role:'admin'}){captured=[];let result;try{const r=await handler(new Request('https://local.invalid/api/stock-ledger?'+new URLSearchParams({from:'2026-10-01',to:'2026-10-31',...params})),env,user);result={status:r.status,body:await r.json()}}catch(e){result={status:e.status,code:e.code}}return {result,queries:[...captured]}}
const cases=[{},...['50H-110.99','51R-047.31','B65006700','does-not-exist','%','_'].map(q=>({q})),...['receipt','issue','recovery','retread','retread_receive'].map(kind=>({kind})),{page:'2'},{direction:'desc'},{from:'2026-10-11',to:'2026-10-20'},{from:'2026-11-01',to:'2026-11-30'}];for(const part_id of parts)for(const stock_state of ['', 'new','recovered','pending_scrap'])for(const q of ['', '50H-110.99','B65006700'])cases.push({part_id,stock_state,q});
const measurements=[];let comparisons=0;
try{for(const params of cases){const a=await call(before.handleStockLedger,params),b=await call(after.handleStockLedger,params);assert.deepEqual(b.result,a.result,'response changed: '+JSON.stringify(params));comparisons++;if(measurements.length<7)measurements.push({params,before:a.queries,after:b.queries});}
for(const user of [{id:'local-perf-wh',role:'warehouse'},{id:'not-granted',role:'warehouse'}])for(const params of [{},{warehouse_id:wh},{part_id:parts[0],q:'B65006700'},{export:'1'}]){const a=await call(before.handleStockLedger,params,user),b=await call(after.handleStockLedger,params,user);assert.deepEqual(b.result,a.result,'permission/export mismatch');comparisons++;}
const initial=await call(before.handleStockLedger,{});for(const row of initial.result.body.data){for(const params of [{view:'children',group_key:row.key,version:String(row.version),page_size:'100'},{view:'children',group_key:row.key,version:String(row.version+1),page_size:'100'},{view:'children',group_key:row.key,version:String(row.version),page:'2',page_size:'50'},{export:'1',q:row.code}]){const a=await call(before.handleStockLedger,params),b=await call(after.handleStockLedger,params);assert.deepEqual(b.result,a.result,'child/export mismatch');comparisons++;}}
fs.writeFileSync('artifacts/ledger-optimization-captured-20261028.json',JSON.stringify(measurements));console.log(JSON.stringify({comparisons,allResponsesUnchanged:true,examples:measurements.map(r=>({filter:r.params,beforeSQL:r.before.length,afterSQL:r.after.length}))},null,2));
}finally{db.close()}
